import React from 'react';

const SearchListItem = ({ hotel }) => {
  return (
    <article className="search-list-item">
      <img src={hotel.image_url} alt={`Image of ${hotel.name}`} />
      <div className="search-list-item__details">
        <h3>{hotel.name}</h3>
        <p><strong>{hotel.distance}</strong> from center</p>
        <p><span className="tag">{hotel.tag}</span></p>
        <p>{hotel.type}</p>
        <p>{hotel.description}</p>
        
        {hotel.free_cancel && (
          <p><span className="free-cancel">Free cancellation</span></p>
        )}

        <div className="search-list-item__footer">
          <span className="price">${hotel.price}</span>
          <div className="rating">
            <span>{hotel.rate_text}</span>
            <span>{hotel.rate}</span>
          </div>
        </div>
      </div>
    </article>
  );
};

export default SearchListItem;
